import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, OnInit, Output, Renderer2 } from '@angular/core';
import { factdata, factIssues, factlinkfiles } from '../../../../../shared/interfaces/fact.interface';
import { DocInfo, myTeamUsers, toolEvents } from '../../../../../pdf/interfaces/pdf.interface';
import { issueList, selectedContactList, selectedIssues, selectedTaskList } from '../../../../../shared/interfaces/issue.interface';
import { ButtonComponent } from '../../../../../shared/components/button/button.component';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { MatMenuModule } from '@angular/material/menu';
import { SourceCardComponent } from '../../../../../shared/components/source-card/source-card.component';
import { codeData } from '../../../../../shared/interfaces/common.interface';
import { CommonModule, DatePipe } from '@angular/common';
import { formType } from '../../../../interfaces/individual.interface';
import { BadgeComponent } from '../../../../../shared/components/badge/badge.component';
import { SelectedIssuesComponent } from '../../../../../shared/components/issues/selected-issues/selected-issues.component';
import { ChooseIssueComponent } from '../../../../../shared/components/issues/choose-issue/choose-issue.component';
import { IssueService } from '../../../../../shared/services/issues/issue.service';
import { MatDialog } from '@angular/material/dialog';
import { FileexplorerComponent } from '../../../../../shared/components/myfiles/fileexplorer/fileexplorer.component';
import { SelectedContactComponent } from '../../../../../shared/components/contacts/selected-contact/selected-contact.component';
import { ChooseContactComponent } from '../../../../../shared/components/contacts/choose-contact/choose-contact.component';
import { ChooseTaskComponent } from '../../../../../shared/components/tasks/choose-task/choose-task.component';
import { SelectedTasksComponent } from '../../../../../shared/components/tasks/selected-tasks/selected-tasks.component';
import { SharedViewComponent } from '../../../../../shared/components/shared-view/shared-view.component';
import { TostbarService } from '../../../../../core/services/tost/tostbar.service';
import { ContactdetailComponent } from '../../../../../shared/components/contacts/contactdetail/contactdetail.component';
import { AvatarComponent } from '../../../../../shared/components/avatar/avatar.component';
import { FactService } from '../../../../../shared/services/fact/fact.service';
import { FactNoteComponent } from '../../../../../pdf/components/facts/fact-note/fact-note.component';
import { FactboxComponent } from '../../../../../pdf/components/facts/factbox/factbox.component';
import { QuickPreviewComponent } from '../../../quick-preview/quick-preview.component';

@Component({
  selector: 'detailform',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [ButtonComponent, IconComponent, MatMenuModule, SourceCardComponent, DatePipe, CommonModule, BadgeComponent,
    ChooseIssueComponent, SelectedContactComponent, ChooseContactComponent, ChooseTaskComponent, SelectedTasksComponent,
    SharedViewComponent, SelectedIssuesComponent, ContactdetailComponent, AvatarComponent, FactNoteComponent, FactboxComponent, QuickPreviewComponent],
  templateUrl: './detailform.component.html',
  styleUrl: './detailform.component.scss'
})
export class DetailformComponent implements OnInit {
  @Input() factData: factdata;
  @Input() docInfo: DocInfo;
  @Input() userList: myTeamUsers[] = [];
  @Input() jTexts: string[] = [];
  @Input() jOT: string[] = [];
  @Input() bIsHighlighted: boolean = false;
  // jEditedTexts: string[] = [];
  @Input() issueList: factIssues[] = [];
  @Input() linkfiles: factlinkfiles[] = [];
  @Input() taskList: selectedTaskList[] = [];
  @Input() contactList: selectedContactList[] = [];
  @Input() FormType: formType = null;
  @Input() nCaseid: string = null;
  originalissueList: issueList[] = [];
  originalrelevences: codeData[] = [];
  originalimpacts: codeData[] = [];
  @Output() OnEvent = new EventEmitter<toolEvents>();
  selectedIssues: selectedIssues[] = [];
  dialogRef: any;
  curruntfact: any;

  addContactForm: boolean = false;
  addTaskForm: boolean = false;
  isDeleting: boolean = false;
  sharedUsers: number;
  constructor(private factService: FactService, private cdr: ChangeDetectorRef, private dialog: MatDialog, private tost: TostbarService) {
  }

  async ngOnInit() {
    debugger;

    this.issueList = [...this.issueList || []];
    this.jTexts = [...this.jTexts || []];
    // this.jEditedTexts = [...this.jTexts || []];
    this.userList = [...this.userList || []];
    this.sharedUsers = this.userList.filter(a => a.isSelected).length;
    this.linkfiles = [...this.linkfiles || []];
    this.taskList = [...this.taskList || []];
    this.contactList = [...this.contactList || []];

    this.selectedIssues = this.issueList.map((item, index) => {
      return {
        nIid: item.nIssueid || item.nIid,
        nImpactid: item.nImpactid,
        nRelid: item.nRelevanceid,
        dt: '',
        nSerial: index + 1
      }
    });
    if (this.linkfiles?.length)
      this.selctfactlink(this.linkfiles[0]);
    this.cdr.detectChanges();
    console.log('detail fact data', this.factData);

  }

  onDataRec(e) {
    this.originalissueList = e.issueList;
    this.originalrelevences = e.relevences;
    this.originalimpacts = e.impacts;
    this.cdr.detectChanges();
  }

  async addFactlink() {
    if (this.dialogRef) return;
    this.dialogRef = this.dialog.open(FileexplorerComponent, {
      width: '90vw',
      height: '90vh',
      panelClass: ['!rounded-[20px]', '!overflow-hidden'], // Enforce rounded corners
      disableClose: true
      // data: {nCaseid:this.nCaseid}
      
    });
    this.dialogRef.componentInstance.nCaseid = this.nCaseid;
    this.dialogRef.componentInstance.isChooser = true;
    this.dialogRef.componentInstance.isIndividual = true;
    this.dialogRef.componentInstance.isLink = 'F';
    this.dialogRef.componentInstance.disabledFiles = this.linkfiles.map(a => a.nBundledetailid);
    this.dialogRef.afterClosed().subscribe(result => {
      try {

        const files = this.dialogRef.componentInstance.choosedFile;
        files.map(a => a.jOTexts = a.texts || []);
        this.linkfiles = [...this.linkfiles, ...files];
      } catch (error) {
      }
      this.dialogRef = null;
      this.cdr.detectChanges();
    });
  }

  back() {
    this.OnEvent.emit({ event: 'CLOSE', data: {} });
  }

  OnCardEvent(e: any, index: number) {
    if (e.type == 'D') {
      this.linkfiles.splice(index, 1);
      this.selctfactlink(this.linkfiles[0]);
      this.cdr.detectChanges
    }
  }

  updateJText(event: Event, index: number): void {
    const target = event.target as HTMLElement;
    this.jTexts[index] = target.innerHTML;
    this.cdr.detectChanges();
  }

  OnContactEvent(e) {
    if (e.event == 'DELETE') {
      this.contactList = this.contactList.filter(a => a.nContactid != e.data.nContactid);
      this.cdr.detectChanges();
    }

  }


  reviewChanges() {
    debugger;
    const issues = []// this.originalissueList.filter(a => this.selectedIssues.find(m=>m.nIid == a.nIssueid));

    this.selectedIssues.forEach(item => {
      const obj = this.originalissueList.find(a => a.nIid == item.nIid);
      if (obj) {
        const imapact = this.originalimpacts.find(a => a.nValue == item.nImpactid);
        const relevance = this.originalrelevences.find(a => a.nValue == (item.nRelid || item.nRelevanceid));
        issues.push({ ...obj, nImpactid: item.nImpactid, nRelevanceid: item.nRelid || item.nRelevanceid, cImpact: imapact ? imapact.cKey : '', cRelevance: relevance ? relevance.cKey : '', nSerial: item.nSerial });
      }
    });

    if (!issues.length) {
      this.tost.error('Please select at least one issue');
      return;
    }

    const mdl = {
      jTexts: this.jTexts,
      issueList: issues,
      linkfiles: this.linkfiles,
      contactList: this.contactList,
      taskList: this.taskList,
      userList: this.userList
    }

    this.OnEvent.emit({ event: 'REVIEW', data: mdl });
  }


  async deleteFact() {
    if (this.isDeleting) return;
    this.isDeleting = true;
    this.cdr.detectChanges();
    const res = await this.factService.deleteFact(this.factData.nFSid);
    this.isDeleting = false;
    this.cdr.detectChanges();
    if (res && res.msg == 1) {
      this.OnEvent.emit({ event: 'DELETE-FACT', data: { nFSid: this.factData.nFSid } });
    } else {
      this.tost.error(`Fact delete failed ${res.error}`);
    }
  }

  selctfactlink(x) {

    console.log(x);
    if (x.isSelected) {
      x.isSelected = false;
      this.curruntfact = null;
    } else {

      this.linkfiles.forEach((item) => {
        item.isSelected = false;
      });
      x.isSelected = true;
      this.curruntfact = x;
    }

    // this.OnEvent.emit({ event: 'VIEW-SOURCE', data: x });
  }

  OnQuickPreviewEvent(e) {
    // debugger;
    // this.onEvent.emit({ event: 'OPEN-FACT-FROM-FACT-SHEET', data: e.data });

  }
  deselect() {
    this.linkfiles.map(e => e.isSelected = false);
    this.curruntfact = null;
  }
}